/// <summary>
/// SysOperation data contract for the label-capture render batch.
/// Carries the processing chunk size and the per-row maximum retry count.
/// </summary>
[DataContractAttribute]
public class AAXWHSLabelCaptureRenderContract
{
    private int chunkSize = 50;
    private int maxRetries = 3;
}

Method.Source:
/// <summary>
/// Number of <c>Pending</c> staging rows processed per batch pass. Default 50.
/// </summary>
/// <param name = "_chunkSize">The chunk size.</param>
/// <returns>The chunk size.</returns>
[DataMemberAttribute,
 SysOperationLabelAttribute("@AAXWarehouseTools:CaptureChunkSize")]
public int parmChunkSize(int _chunkSize = chunkSize)
{
    chunkSize = _chunkSize;

    return chunkSize;
}

/// <summary>
/// Maximum render attempts before a failing row is marked <c>Poison</c>. Default 3.
/// </summary>
/// <param name = "_maxRetries">The maximum retry count.</param>
/// <returns>The maximum retry count.</returns>
[DataMemberAttribute,
 SysOperationLabelAttribute("@AAXWarehouseTools:CaptureMaxRetries")]
public int parmMaxRetries(int _maxRetries = maxRetries)
{
    maxRetries = _maxRetries;

    return maxRetries;
}
